#include <algorithm>
#include <vector>
#include <iostream>

int main() {
    std::vector<int> data = {5, 2, 9, 1, 5, 6};
    // Sort the entire vector using iterators
    std::sort(data.begin(), data.end());
    // Output sorted data
    for (const auto& num : data) {
        std::cout << num << ' ';
    }
    return 0;
}
